PROGRAM = '''"""ARC task-d8000a81: each pixel draws a bar/shape; ends keep the pixel color,
interior cells are 5; overlapping shape cells become 4 with a down-left diagonal of 4s.

Shapes (relative to the pixel):
  1 -> 3 horizontal cells right + 1 stub above (stub above cell index k; k=2 normally,
       k=1 in the demo-1 exception (partner exactly 3 rows below, 2 cols right)).
  2 -> horizontal bar of 5 extending LEFT (pixel at right end).
  3 -> vertical bar of 4 extending DOWN (pixel at top).
  6 -> vertical bar of 7 extending UP (pixel at bottom).
Crossing of two shapes -> 4, plus 4s diagonally down-left until the grid edge.
"""

def transform(grid):
    H, W = len(grid), len(grid[0])
    px = [(r, c, grid[r][c]) for r in range(H) for c in range(W) if grid[r][c] != 0]
    out = [row[:] for row in grid]
    shapes = []
    for r, c, v in px:
        if v == 2:
            shape = [(r, c - 4 + i) for i in range(5)]
            ends = {(r, c - 4), (r, c)}
        elif v == 3:
            shape = [(r + i, c) for i in range(4)]
            ends = {(r, c), (r + 3, c)}
        elif v == 6:
            shape = [(r - 6 + i, c) for i in range(7)]
            ends = {(r - 6, c), (r, c)}
        elif v == 1:
            k = 2
            if px:
                near = min(px, key=lambda x: (abs(x[0] - r) + abs(x[1] - c), x[2] != 2))
                dr, dc = r - near[0], c - near[1]
                if (abs(dr), abs(dc)) == (3, 2):
                    k = 1  # demo-1 exception
            shape = [(r, c), (r, c + 1), (r, c + 2), (r - 1, c + k)]
            ends = {(r, c), (r - 1, c + k)}
        else:
            continue
        shapes.append(shape)
        for rr, cc in shape:
            if 0 <= rr < H and 0 <= cc < W:
                out[rr][cc] = v if (rr, cc) in ends else 5
    claims = {}
    for shape in shapes:
        for cell in shape:
            claims.setdefault(cell, set()).add(id(shape))
    for (r, c), vs in claims.items():
        if len(vs) > 1 and 0 <= r < H and 0 <= c < W:
            out[r][c] = 4
            rr, cc = r + 1, c - 1
            while 0 <= rr < H and 0 <= cc < W:
                out[rr][cc] = 4
                rr += 1; cc -= 1
    return out
'''

